# Dynamic dispatch at nested call sites: a method call with a statically
# unknown receiver used as a value inside arithmetic, as a function argument,
# in a return, and assigned to a variable. Exercises the AOT dispatch switch
# from every expression position (all-call-site dispatch).
class Animal:
    def __init__(self):
        self.x = 1
    def speak(self):
        return self.x
class Dog(Animal):
    def __init__(self):
        super().__init__()
    def speak(self):
        return 42
def make(kind):
    if kind == 1:
        return Animal()
    return Dog()
def add(a, b):
    return a + b
def get(v):
    return v.speak()
print(make(1).speak() + make(2).speak())
print(add(make(1).speak(), make(2).speak()))
print(get(make(1)) + get(make(2)))
c = Animal()
d = Dog()
print(c.speak() + d.speak())
print("done")

# Gap A reproducer: an instance handle stored in a local variable must stay
# alive across a later allocation that triggers GC. Expected: 43.
class Animal:
    def __init__(self):
        self.x = 1
    def speak(self):
        return self.x
class Dog(Animal):
    def __init__(self):
        super().__init__()
    def speak(self):
        return 42
def make(kind):
    if kind == 1:
        return Animal()
    return Dog()
def f():
    a = make(1)
    b = make(2)
    return a.speak() + b.speak()
print(f())

# Gap A (ADR 0151): a polymorphic receiver that survives many real GC
# collections + slot reuse must dispatch on the *live* instance. Unlike
# dispatch_gc.gy (2 allocations, no collection), this forces the 1024-slot
# heap to fill and free/reuse slots repeatedly while two receivers stay
# reachable, then dispatches on both. Expected: 1 + 42 = 43.
class Animal:
    def __init__(self):
        self.x = 1
    def speak(self):
        return self.x
class Dog(Animal):
    def __init__(self):
        super().__init__()
    def speak(self):
        return 42
def make(kind):
    if kind == 1:
        return Animal()
    return Dog()
def f():
    a = make(1)
    b = make(2)
    for i in range(2000):
        lst = [i]
    return a.speak() + b.speak()
print(f())

def add1(g):
    def wrap(x):
        return g(x) + 1
    return wrap
@add1
def f(x):
    return x * 2
print(f(3))

# Variance + generics (L6.6): nominal class annotations accept subclass
# instances, read-only Sequence annotations accept any container, and invariant
# list/dict annotations keep their element types — identical on both backends.

class Animal:
    def speak(self):
        return 1

class Dog(Animal):
    def speak(self):
        return 2

class Puppy(Dog):
    def speak(self):
        return 3

# a nominal base-class annotation accepts instances of the class and subclasses
def feed(a: Animal) -> int:
    return a.speak()

print(feed(Animal()))
print(feed(Dog()))
print(feed(Puppy()))

# annotated containers keep working (list[T] is invariant in T)
